describe('Ascii85Stream.readBlock', () => {
  const Ascii85Stream = getAscii85StreamClass();

  function createStreamFromBytes(bytes) {
    const fake = new FakeStream(bytes);
    const inst = new Ascii85Stream(fake, 0);

    // Patch internal state to predictable defaults for tests
    inst.bufferLength = 0;
    inst.eof = false;
    inst.buffer = new Uint8Array(0);
    inst.input = new Uint8Array(5);
    inst.ensureBuffer = function(n) {
      this.buffer = new Uint8Array(n);
      return this.buffer;
    };
    return { inst, fake };
  }

  test('readBlock sets eof on empty input', () => {
    const { inst } = createStreamFromBytes([]);
    inst.readBlock();
    expect(inst.eof).toBe(true);
    expect(inst.bufferLength).toBe(0);
    expect(inst.buffer.length).toBe(0);
  });

  test('readBlock handles tilde as EOF indicator', () => {
    const { inst } = createStreamFromBytes([0x7e]); // '~'
    inst.readBlock();
    // Should set eof and not produce output
    expect(inst.eof).toBe(true);
  });

  test('readBlock decodes a normal 5-char block (A!!!!) to 4 bytes', () => {
    const { inst } = createStreamFromBytes([0x41, 0x21, 0x21, 0x21, 0x21]); // 'A!!!!'
    inst.readBlock();
    // Expect 4 output bytes: [99, 144, 150, 32]
    expect(inst.bufferLength).toBe(4);
    expect(Array.from(inst.buffer.subarray(0, 4))).toEqual([99, 144, 150, 32]);
    expect(inst.eof).toBe(false);
  });

  test('readBlock skips leading whitespace and decodes following block', () => {
    const { inst } = createStreamFromBytes([0x20, 0x20, 0x21, 0x21, 0x21, 0x21]); // "  !!!!"
    inst.readBlock();
    // Expect 4 output bytes: [99, 144, 150, 32]
    expect(inst.bufferLength).toBe(4);
    expect(Array.from(inst.buffer.subarray(0, 4))).toEqual([99, 144, 150, 32]);
    expect(inst.eof).toBe(false);
  });

  test('readBlock handles z (special 4 zero bytes) path', () => {
    const { inst } = createStreamFromBytes([0x7a]); // 'z'
    inst.readBlock();
    expect(inst.bufferLength).toBe(4);
    expect(Array.from(inst.buffer.subarray(0, 4))).toEqual([0, 0, 0, 0]);
    expect(inst.eof).toBe(false);
  });

  test('readBlock after z path returns eof when more data is requested', () => {
    const { inst } = createStreamFromBytes([0x7a, 0x7e]); // 'z' then '~' but '~' would be consumed after z in a real stream; here next readBlock will see -1
    inst.readBlock();
    expect(inst.bufferLength).toBe(4);
    inst.readBlock(); // second call should set eof if next byte is EOF
    expect(inst.eof).toBe(true);
  });
});

